INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/22 14:59:59", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", -470, "クローチェ", 10001, 2002, 2, 126401, 1, 1, "2023/06/30 12:00:00", 1, 0, 1.47);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/22 14:59:59", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", -470, "クローチェ", 10002, 2002, 1, 126401, 1, 2, "2023/06/30 12:00:00", 2, 0, 2.15);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/22 14:59:59", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", -470, "ライラエル", 10003, 2002, 2, 126501, 1, 2, "2023/06/30 12:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/09/22 14:59:59", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", -470, "ライラエル", 10004, 2002, 1, 126501, 1, 1, "2023/06/30 12:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/22 14:59:59", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", -470, "リンド", 10005, 2002, 2, 127702, 2, 2, "2023/09/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/22 14:59:59", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", -470, "リンド", 10006, 2002, 2, 127702, 2, 2, "2023/09/15 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/22 14:59:59", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", -470, "ヴルム", 10007, 2002, 1, 127802, 2, 1, "2023/09/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2023/12/22 14:59:59", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", -470, "ヴルム", 10008, 2002, 1, 127802, 2, 2, "2023/09/15 15:00:00", 2, 0, 6.5);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/22 14:59:59", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", -470, "アネモネ", 10009, 2002, 1, 129602, 3, 2, "2023/12/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/22 14:59:59", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", -470, "アネモネ", 10010, 2002, 1, 129602, 3, 2, "2023/12/15 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/22 14:59:59", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", -470, "ネフィ=ネラ", 10011, 2002, 1, 129701, 3, 1, "2023/12/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/03/22 14:59:59", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", -470, "ネフィ=ネラ", 10012, 2002, 1, 129701, 3, 2, "2023/12/15 15:00:00", 2, 0, 6.2);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/22 14:59:59", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", -470, "カノン", 10013, 2002, 5, 130301, 4, 3, "2024/03/15 15:00:00", 1, 0, 3.1);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/22 14:59:59", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", -470, "カノン", 10014, 2002, 2, 130301, 4, 3, "2024/03/15 15:00:00", 2, 0, 6.15);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/22 14:59:59", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", -470, "ナーナ", 10015, 2002, 2, 130401, 4, 2, "2024/03/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/06/22 14:59:59", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", -470, "ナーナ", 10016, 2002, 1, 130401, 4, 2, "2024/03/15 15:00:00", 2, 0, 3.35);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/22 14:59:59", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", -470, "ホウオウ", 10017, 2002, 1, 130502, 5, 1, "2024/06/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/22 14:59:59", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", -470, "ホウオウ", 10018, 2002, 1, 130502, 5, 2, "2024/06/15 15:00:00", 2, 0, 3.18);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/22 14:59:59", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", -470, "ホウオウ", 10019, 2002, 4, 130503, 5, 4, "2024/06/15 15:00:00", 3, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/22 14:59:59", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", -470, "ネア", 10020, 2002, 2, 123301, 5, 1, "2024/06/15 15:00:00", 1, 0, 4.9);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/09/22 14:59:59", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", -470, "ネア", 10021, 2002, 2, 123301, 5, 1, "2024/06/15 15:00:00", 2, 0, 4.8);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/22 14:59:59", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", -470, "カリザ", 10022, 2002, 1, 133301, 6, 3, "2024/09/15 15:00:00", 1, 0, 4.922);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/22 14:59:59", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", -470, "カリザ", 10023, 2002, 5, 133301, 6, 3, "2024/09/15 15:00:00", 2, 0, 9.638);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/22 14:59:59", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", -470, "ミーア", 10024, 2002, 2, 133401, 6, 1, "2024/09/15 15:00:00", 1, 0, 2.88);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2024/12/22 14:59:59", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", -470, "ミーア", 10025, 2002, 1, 133401, 6, 5, "2024/09/15 15:00:00", 2, 0, 4.818);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/22 14:59:59", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", -470, "グレイス", 10026, 2002, 1, 133002, 7, 2, "2024/12/15 15:00:00", 1, 0, 1.78);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/22 14:59:59", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", -470, "グレイス", 10027, 2002, 7, 133002, 7, 1, "2024/12/15 15:00:00", 2, 0, 6.15);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/22 14:59:59", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", -470, "ヴァイオレット", 10028, 2002, 2, 133102, 7, 6, "2024/12/15 15:00:00", 1, 0, 4.28);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/03/22 14:59:59", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", -470, "ヴァイオレット", 10029, 2002, 1, 133102, 7, 1, "2024/12/15 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/23 14:59:59", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", -470, "ルルィ", 10030, 2002, 1, 136902, 8, 2, "2025/03/15 15:00:00", 1, 0, 5.53);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/23 14:59:59", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", -470, "ルルィ", 10031, 2002, 7, 136902, 8, 9, "2025/03/15 15:00:00", 2, 0, 6.05);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/23 14:59:59", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", -470, "デュラン", 10032, 2002, 1, 137001, 8, 2, "2025/03/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/06/23 14:59:59", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", -470, "デュラン", 10033, 2002, 1, 137001, 8, 2, "2025/03/15 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/23 14:59:59", "おう\n好きなもん持ってきな", -470, "サツキ", 10034, 2002, 2, 135902, 9, 2, "2025/06/16 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/23 14:59:59", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", -470, "サツキ", 10035, 2002, 6, 135902, 9, 1, "2025/06/16 15:00:00", 2, 0, 4.935);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/23 14:59:59", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", -470, "ユキノ", 10036, 2002, 5, 135802, 9, 2, "2025/06/16 15:00:00", 1, 0, 7.441);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/09/23 14:59:59", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", -470, "ユキノ", 10037, 2002, 7, 135802, 9, 7, "2025/06/16 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/22 14:59:59", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", -470, "クルル", 10038, 2002, 2, 130901, 10, 2, "2025/09/16 15:00:00", 1, 0, 2.295);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/22 14:59:59", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", -470, "クルル", 10039, 2002, 6, 130901, 10, 1, "2025/09/16 15:00:00", 2, 0, 6.281);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/22 14:59:59", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", -470, "ヴォルガーノ", 10040, 2002, 1, 137701, 10, 2, "2025/09/16 15:00:00", 1, 0, 5.549);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2025/12/22 14:59:59", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", -470, "ヴォルガーノ", 10041, 2002, 6, 137701, 10, 3, "2025/09/16 15:00:00", 2, 0, 2.64);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/23 11:59:59", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", -470, "ライラエル", 10042, 2002, 4, 132801, 11, 7, "2025/12/15 15:00:00", 1, 0, 7.642);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/23 11:59:59", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", -470, "ライラエル", 10043, 2002, 1, 132802, 11, 1, "2025/12/15 15:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/23 11:59:59", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", -470, "クローチェ", 10044, 2002, 1, 134502, 11, 1, "2025/12/15 15:00:00", 1, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/03/23 11:59:59", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", -470, "クローチェ", 10045, 2002, 1, 134501, 11, 2, "2025/12/15 15:00:00", 2, 0, 3.72);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/22 11:59:59", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", -470, "ネフィ＝ネラ", 10046, 2002, 1, 138201, 12, 2, "2026/03/16 12:00:00", 1, 0, 4.991);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/22 11:59:59", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", -470, "ネフィ＝ネラ", 10047, 2002, 4, 138201, 12, 1, "2026/03/16 12:00:00", 2, 0, 3.877);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/22 11:59:59", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", -470, "アラクネ", 10048, 2002, 6, 136001, 12, 4, "2026/03/16 12:00:00", 1, 0, 1.71);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/06/22 11:59:59", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", -470, "アラクネ", 10049, 2002, 2, 136001, 12, 5, "2026/03/16 12:00:00", 2, 0, 5.32);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/22 11:59:59", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", -470, "アネモネ", 10050, 2002, 4, 135401, 13, 9, "2026/06/15 12:00:00", 1, 0, 3.727);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/22 11:59:59", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", -470, "アネモネ", 10051, 2002, 9, 135401, 13, 7, "2026/06/15 12:00:00", 2, 0, 7.213);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/22 11:59:59", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", -470, "クリア", 10052, 2002, 2, 135301, 13, 1, "2026/06/15 12:00:00", 1, 0, 1.874);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/09/22 11:59:59", "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", -470, "クリア", 10053, 2002, 2, 135301, 13, 2, "2026/06/15 12:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/12/22 11:59:59", "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", -470, "ヴァイオレット", 10054, 2002, 1, 138001, 14, 2, "2026/09/15 12:00:00", 1, 0, 4.215);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/12/22 11:59:59", "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", -470, "ヴァイオレット", 10055, 2002, 4, 138001, 14, 4, "2026/09/15 12:00:00", 2, 0, 0);
INSERT INTO `v1_db2e0c95224735ed307339d7a3faea70a1548b591325f21b7de966a627e36084` VALUES ("2026/12/22 11:59:59", "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", -470, "グレイス", 10056, 2002, 1, 138901, 14, 6, "2026/09/15 12:00:00", 1, 0, 5.477);
